function validate(input) {
  const [{ Posts = [] }] = input;
  const ids = new Set();
  for (const [id, user, date] of Posts) {
    if (id === null || user === null) return 'Every post needs a post_id and a user_id.';
    if (ids.has(id)) return `post_id ${id} appears twice.`;
    ids.add(id);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date ?? '') || Number.isNaN(Date.parse(date))) return `Post ${id} needs a date like 2024-02-01.`;
  }
  return null;
}

