function generate(rand, size) {
  const small = size === 'small';
  const stamp = offset => new Date(Date.UTC(2024, 1, 1) + offset * 86400000).toISOString().slice(0, 10);
  const users = small ? 1 + Math.floor(rand() * 4) : 160;
  const Posts = [];
  let id = 0;
  for (let u = 1; u <= users && (!small || Posts.length < 8); u++) {
    const user = small ? u : u * 2 + 3;
    const count = small ? Math.floor(rand() * 5) : 3 + Math.floor(rand() * 10);
    // Bursty users post inside a short stretch; steady users spread posts over the month and a little beyond.
    const bursty = rand() < 0.5;
    const from = bursty ? Math.floor(rand() * 26) : -3, span = bursty ? 2 + Math.floor(rand() * 7) : 33;
    for (let k = 0; k < count && (!small || Posts.length < 8); k++) Posts.push([0, user, stamp(from + Math.floor(rand() * span))]);
  }
  for (let i = Posts.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [Posts[i], Posts[j]] = [Posts[j], Posts[i]];
  }
  for (const row of Posts) row[0] = ++id;
  return [{ Posts }];
}
